    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # Boundary sequences (the examples have pattern sequences in the bottom
    # row, sometimes with two sequences separated by zeros).
    templates = []
    for r in (0, h - 1):
        c = 0
        while c < w:
            while c < w and g[r][c] == 0:
                c += 1
            s = c
            while c < w and g[r][c] != 0:
                c += 1
            if c - s >= 3:
                templates.append(g[r][s:c])
    # In the demos each isolated colored marker refers to the unique template
    # containing its color; place that template starting at the marker's cell.
    border_cells = {(r, c) for r in (0, h-1) for c in range(w) if g[r][c]}
    for r in range(h):
        for c in range(w):
            v = g[r][c]
            if not v or (r, c) in border_cells:
                continue
            matches = [t for t in templates if v in t]
            if len(matches) != 1:
                continue
            t = matches[0]
            k = t.index(v)
            start = c - k
            for j, x in enumerate(t):
                cc = start + j
                if 0 <= cc < w:
                    g[r][cc] = x
    return g

